-- Executed after the shared Ensembl core seed from duckvep_ensembl.test.
-- Both source programmes use their original Ensembl coordinates and code assignments.
CREATE TABLE rna_regions AS SELECT seq_region, sequence_length FROM query(duckvep_ensembl_regions_sql('duckvep_core', 'duckvep_reference_chunks', 'GRCh38'));
INSERT INTO duckvep_core.transcript VALUES (33, 21, 10, 21, 32, -1, 'protein_coding', 1, 'ENST_TEST_RNA_ONLY', 1);
INSERT INTO duckvep_core.exon_transcript VALUES (42, 33, 1);
INSERT INTO duckvep_core.translation VALUES (53, 33, 1, 42, 9, 42, 'ENSP_TEST_RNA_ONLY', 1);
INSERT INTO duckvep_core.transcript_attrib VALUES (33, 65, '4 5 TT');
UPDATE duckvep_core.transcript_attrib SET value = '4 5 TT' WHERE transcript_id = 32 AND attrib_type_id = 65;
CREATE TABLE reverse_tx AS SELECT * FROM query(duckvep_ensembl_transcripts_sql('duckvep_core', 'duckvep_reference_chunks', 'GRCh38'));
CREATE TABLE reverse_rna AS SELECT * FROM query(duckvep_ensembl_rna_edits_sql('duckvep_core', 'reverse_tx'));
SELECT CASE WHEN (SELECT typeof(rna_cds_cdna_start) = 'UBIGINT' AND typeof(rna_cds_cdna_end) = 'UBIGINT' AND typeof(rna_codon_table) = 'UTINYINT' FROM reverse_tx LIMIT 1) THEN true ELSE error('reverse RNA input types') END;
SELECT CASE WHEN (SELECT count(*) FROM reverse_tx WHERE transcript_index = 3 AND cds_sequence IS NULL AND codon_table IS NULL AND rna_cds_cdna_start = 1 AND rna_cds_cdna_end = 9 AND rna_codon_table = 2 AND transcript_flags & 131072 = 0) = 1 AND (SELECT count(*) FROM reverse_tx WHERE transcript_index = 2 AND transcript_flags & 131072 != 0) = 1 AND (SELECT count(*) FROM reverse_rna WHERE transcript_index = 3 AND cdna_start = 4 AND expected_substrate = 'CC' AND alternate_sequence = 'TT' AND operation_kind = 'replacement' AND programme_name = 'Ensembl116:_rna_edit' AND evidence_name = 'transcript_attrib:SeqEdit' AND boundary_overrides = 0) = 1 THEN true ELSE error('reverse producer and source veto') END;
COPY (SELECT * FROM rna_regions ORDER BY seq_region) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-reverse', RELATION 'regions', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
COPY (SELECT transcript_index, seq_region, transcript_start, transcript_end, strand, gene_index, transcript_flags, cds_start, cds_end, cds_sequence, codon_table, pre_cds_sequence, post_cds_sequence, cdna_sequence, rna_cds_cdna_start, rna_cds_cdna_end, rna_codon_table FROM reverse_tx ORDER BY seq_region, transcript_start, transcript_index) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-reverse', RELATION 'transcripts', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
COPY (SELECT transcript_index, exon.exon_start, exon.exon_end, exon.exon_cdna_start, exon.exon_cdna_end, exon.phase, exon.end_phase FROM reverse_tx, LATERAL unnest(exons) AS u(exon) ORDER BY transcript_index, exon.exon_cdna_start) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-reverse', RELATION 'exons', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
COPY (SELECT * FROM reverse_rna ORDER BY transcript_index, cdna_start DESC) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-reverse', RELATION 'rna_edits', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
SELECT CASE WHEN duckvep_model_publish('rna-reverse') THEN true ELSE error('reverse publish') END;
SELECT CASE WHEN duckvep_model_save('rna-reverse', '__RNA_TMP__/reverse.dvsnap') THEN true ELSE error('reverse save') END;
COPY (SELECT 1::UBIGINT event_index, 0::UINTEGER seq_region, 26::UBIGINT position, 'A' reference, 'G' alternate, 1::UINTEGER alt_index, 3::UINTEGER transcript_index, 1::UINTEGER sample_index, [1,0]::INTEGER[] alleles, [false,true]::BOOLEAN[] phase_before, NULL::BIGINT phase_set, [NULL]::BIGINT[] phase_sets, 1::BIGINT copies, 1::BIGINT versions, 1::BIGINT ploidies) TO 'x' (FORMAT duckvep_stage, JOB 'rna-reverse-job', MODEL 'rna-reverse', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
CREATE TABLE reverse_result AS SELECT * FROM duckvep_haplotype_scan('rna-reverse-job');
SELECT CASE WHEN count(*) = 1 AND bool_and(prediction_status = 'conditional_assumed_rna_programme' AND prediction_reason = 'assumed_rna_programme' AND prediction_reference_protein = 'MF*' AND prediction_protein = 'MFQ*' AND cds IS NULL AND protein IS NULL AND haplotype_consequences IS NULL AND haplotype_impact IS NULL AND nmd_prediction = 'unknown') THEN true ELSE error('reverse conditional result') END FROM reverse_result WHERE transcript_index = 3;
COPY (SELECT 1::UBIGINT event_index, 0::UINTEGER seq_region, 26::UBIGINT position, 'A' reference, 'G' alternate, 1::UINTEGER alt_index, 2::UINTEGER transcript_index, 1::UINTEGER sample_index, [1,0]::INTEGER[] alleles, [false,true]::BOOLEAN[] phase_before, NULL::BIGINT phase_set, [NULL]::BIGINT[] phase_sets, 1::BIGINT copies, 1::BIGINT versions, 1::BIGINT ploidies) TO 'x' (FORMAT duckvep_stage, JOB 'rna-initial-met-veto', MODEL 'rna-reverse', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
SELECT CASE WHEN (SELECT count(*) FROM duckvep_haplotype_scan('rna-initial-met-veto') WHERE prediction_status = 'conditional_assumed_rna_programme') = 0 THEN true ELSE error('initial_met veto') END;
DELETE FROM duckvep_core.transcript_attrib WHERE transcript_id = 33;
UPDATE duckvep_core.transcript_attrib SET value = '4 5 A' WHERE transcript_id = 32 AND attrib_type_id = 65;
DELETE FROM duckvep_core.translation WHERE translation_id = 53;
DELETE FROM duckvep_core.exon_transcript WHERE transcript_id = 33;
DELETE FROM duckvep_core.transcript WHERE transcript_id = 33;
UPDATE duckvep_reference_chunks SET seq = substr(seq, 1, 6) || 'TAA' || substr(seq, 10) WHERE "start" = 20;
UPDATE duckvep_core.seq_region_attrib SET value = '1' WHERE seq_region_id = 10 AND attrib_type_id = 66;
INSERT INTO duckvep_core.exon VALUES (44, 10, 21, 32, 1, 0, 0, 1, 'ENSE_TEST_RNA_PLUS');
INSERT INTO duckvep_core.transcript VALUES (35, 21, 10, 21, 32, 1, 'protein_coding', 1, 'ENST_TEST_RNA_PLUS', 1);
INSERT INTO duckvep_core.exon_transcript VALUES (44, 35, 1);
INSERT INTO duckvep_core.translation VALUES (55, 35, 1, 44, 9, 44, 'ENSP_TEST_RNA_PLUS', 1);
INSERT INTO duckvep_core.transcript_attrib VALUES (35, 65, '1 3 ATG');
CREATE TABLE forward_tx AS SELECT * FROM query(duckvep_ensembl_transcripts_sql('duckvep_core', 'duckvep_reference_chunks', 'GRCh38'));
CREATE TABLE forward_rna AS SELECT * FROM query(duckvep_ensembl_rna_edits_sql('duckvep_core', 'forward_tx'));
SELECT CASE WHEN (SELECT typeof(rna_cds_cdna_start) = 'UBIGINT' AND typeof(rna_cds_cdna_end) = 'UBIGINT' AND typeof(rna_codon_table) = 'UTINYINT' FROM forward_tx LIMIT 1) THEN true ELSE error('forward RNA input types') END;
SELECT CASE WHEN (SELECT count(*) FROM forward_tx WHERE transcript_index = 3 AND cds_sequence IS NULL AND codon_table IS NULL AND rna_cds_cdna_start = 1 AND rna_cds_cdna_end = 9 AND rna_codon_table = 1 AND CAST(cdna_sequence AS VARCHAR) = 'CCTTTATAACAT') = 1 AND (SELECT count(*) FROM forward_tx WHERE transcript_index = 2 AND transcript_flags & 131072 != 0) = 1 AND (SELECT count(*) FROM forward_rna WHERE transcript_index = 3 AND cdna_start = 1 AND expected_substrate = 'CCT' AND alternate_sequence = 'ATG' AND operation_kind = 'substitution' AND programme_name = 'Ensembl116:_rna_edit' AND evidence_name = 'transcript_attrib:SeqEdit' AND boundary_overrides = 0) = 1 THEN true ELSE error('forward producer') END;
COPY (SELECT * FROM rna_regions ORDER BY seq_region) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-forward', RELATION 'regions', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
COPY (SELECT transcript_index, seq_region, transcript_start, transcript_end, strand, gene_index, transcript_flags, cds_start, cds_end, cds_sequence, codon_table, pre_cds_sequence, post_cds_sequence, cdna_sequence, rna_cds_cdna_start, rna_cds_cdna_end, rna_codon_table FROM forward_tx ORDER BY seq_region, transcript_start, transcript_index) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-forward', RELATION 'transcripts', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
COPY (SELECT transcript_index, exon.exon_start, exon.exon_end, exon.exon_cdna_start, exon.exon_cdna_end, exon.phase, exon.end_phase FROM forward_tx, LATERAL unnest(exons) AS u(exon) ORDER BY transcript_index, exon.exon_cdna_start) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-forward', RELATION 'exons', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
COPY (SELECT * FROM forward_rna ORDER BY transcript_index, cdna_start DESC) TO 'x' (FORMAT duckvep_stage, MODEL 'rna-forward', RELATION 'rna_edits', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
SELECT CASE WHEN duckvep_model_publish('rna-forward') THEN true ELSE error('forward publish') END;
SELECT CASE WHEN duckvep_model_save('rna-forward', '__RNA_TMP__/forward.dvsnap') THEN true ELSE error('forward save') END;
COPY (SELECT 2::UBIGINT event_index, 0::UINTEGER seq_region, 25::UBIGINT position, 'T' reference, 'C' alternate, 1::UINTEGER alt_index, 3::UINTEGER transcript_index, 1::UINTEGER sample_index, [1,0]::INTEGER[] alleles, [false,true]::BOOLEAN[] phase_before, NULL::BIGINT phase_set, [NULL]::BIGINT[] phase_sets, 1::BIGINT copies, 1::BIGINT versions, 1::BIGINT ploidies) TO 'x' (FORMAT duckvep_stage, JOB 'rna-forward-job', MODEL 'rna-forward', USE_TMP_FILE FALSE, PRESERVE_ORDER TRUE);
CREATE TABLE forward_result AS SELECT * FROM duckvep_haplotype_scan('rna-forward-job');
SELECT CASE WHEN count(*) = 1 AND bool_and(prediction_status = 'conditional_assumed_rna_programme' AND prediction_reason = 'assumed_rna_programme' AND prediction_reference_protein = 'ML*' AND prediction_protein = 'MS*' AND cds IS NULL AND protein IS NULL AND haplotype_consequences IS NULL AND haplotype_impact IS NULL AND nmd_prediction = 'unknown') THEN true ELSE error('forward conditional result') END FROM forward_result WHERE transcript_index = 3;
SELECT 'fingerprint-forward', _duckvep_model_fingerprint('rna-forward') UNION ALL SELECT 'fingerprint-reverse', _duckvep_model_fingerprint('rna-reverse') ORDER BY 1;
SELECT 'full-forward', sha256(string_agg(to_json(r), '|' ORDER BY to_json(r))) FROM forward_result r UNION ALL SELECT 'full-reverse', sha256(string_agg(to_json(r), '|' ORDER BY to_json(r))) FROM reverse_result r ORDER BY 1;
SELECT 'reverse' AS scenario, prediction_status, prediction_reason, prediction_reference_protein, prediction_protein, cds, protein, haplotype_consequences, haplotype_impact, nmd_prediction FROM reverse_result WHERE transcript_index = 3 UNION ALL SELECT 'forward', prediction_status, prediction_reason, prediction_reference_protein, prediction_protein, cds, protein, haplotype_consequences, haplotype_impact, nmd_prediction FROM forward_result WHERE transcript_index = 3 ORDER BY scenario;
SELECT CASE WHEN duckvep_model_drop('rna-reverse') AND duckvep_model_drop('rna-forward') AND NOT duckvep_haplotype_drop('rna-reverse-job') AND NOT duckvep_haplotype_drop('rna-forward-job') THEN true ELSE error('live cleanup') END;
